import { z } from "zod";
import type { AgentAction } from "./actions";

export const PROTOCOL_VERSION = "v1" as const;

type Version = typeof PROTOCOL_VERSION;

export type SessionPhase = "idle" | "starting" | "running" | "error";
export type TurnEffort = string;
export type RuntimeModelOption = {
  id: string;
  model: string;
  displayName: string;
  description: string;
  supportedReasoningEfforts: Array<{
    reasoningEffort: string;
    description: string;
  }>;
  defaultReasoningEffort: string | null;
  isDefault: boolean;
};

export type SessionAgentConfig = {
  id: string;
  name: string;
  model?: string | undefined;
  effort?: TurnEffort | undefined;
  personaPrompt?: string | undefined;
};

export type SessionStartPayload = {
  seed?: number | undefined;
  model?: string | undefined;
  effort?: TurnEffort | undefined;
  agents: SessionAgentConfig[];
};

export type ClientMessage =
  | {
      version: Version;
      type: "session.start";
      payload: SessionStartPayload;
    }
  | {
      version: Version;
      type: "god.send";
      payload: { text: string; targetAgentId?: string | undefined };
    }
  | {
      version: Version;
      type: "build.request";
      payload: { goal: string };
    }
  | {
      version: Version;
      type: "agent.pause";
      payload: Record<string, never>;
    }
  | {
      version: Version;
      type: "agent.resume";
      payload: Record<string, never>;
    }
  | {
      version: Version;
      type: "session.reset";
      payload: {
        seed?: number | undefined;
      };
    };

export type WorldNearbyEntity = {
  id: string;
  type: string;
  x: number;
  y: number;
  distance: number;
  hp?: number;
  maxHp?: number;
