};

type WorldResourceEntityMessage = {
  id: string;
  type: "resource";
  subtype: string;
  x: number;
  y: number;
  quantity: number;
};

type WorldCreatureEntityMessage = {
  id: string;
  type: "creature";
  subtype: string;
  x: number;
  y: number;
  quantity: number;
  hp: number;
  maxHp: number;
  attack: number;
  defense: number;
  aggroRange: number;
  attackRange: number;
  cooldownTicks: number;
  maxCooldownTicks: number;
  hostile: boolean;
  behaviorState: "idle" | "chase" | "attack";
};

export type ServerMessage =
  | {
      version: Version;
      type: "session.state";
      payload: {
        phase: SessionPhase;
        paused: boolean;
