          y: number;
          facing: string;
          stamina: number;
          hp: number;
          maxHp: number;
          attack: number;
          defense: number;
          attackRange: number;
          cooldownTicks: number;
          alive: boolean;
          inventory: Record<string, number>;
          score: {
            survival: number;
            progression: number;
            social: number;
            total: number;
          };
          scoreTrack: {
            creatureKills: number;
            enemyAgentKills: number;
            successfulLoots: number;
            crafts: number;
            structuresPlaced: number;
            cooperativeTalks: number;
            tacticalInspects: number;
            idleStreak: number;
          };
          knownPeerInventories: Record<
            string,
            {
              inventory: Record<string, number>;
              tick: number;
            }
          >;
          nearbyEntities: WorldNearbyEntity[];
          relations: {
