          effort: TurnEffort;
        }>;
        catalog: {
          prefabs: Array<{
            id: string;
            name: string;
            kind: string;
          }>;
          recipes: Array<{
            id: string;
            input: Array<{
              item: string;
              count: number;
            }>;
            output: {
              item: string;
              count: number;
            };
          }>;
        };
      };
    }
  | {
      version: Version;
      type: "agent.turn";
      payload: {
        agentId: string;
        turnId: string;
        status: "started" | "completed" | "failed" | "interrupted";
        latencyMs: number;
        usage?: {
          inputTokens: number;
          outputTokens: number;
          cachedInputTokens: number;
        };
      };
    }
  | {
      version: Version;
      type: "agent.action";
      payload: {
        agentId: string;
        action: AgentAction;
        result: "accepted" | "invalid" | "applied" | "rejected";
        reason?: string;
      };
    }
  | {
      version: Version;
      type: "agent.feed";
      payload: {
        agentId?: string;
        role: "god" | "agent" | "system" | "reasoning";
        text: string;
      };
    }
  | {
      version: Version;
      type: "build.result";
      payload: {
        status: "success" | "failed";
        changedFiles: string[];
        summary: string;
      };
    }
  | {
      version: Version;
      type: "error";
      payload: {
        code: string;
        message: string;
        recoverable: boolean;
      };
    };

const sessionAgentSchema = z.object({
  id: z.string().min(1).max(64),
  name: z.string().min(1).max(80),
  model: z.string().min(1).max(120).optional(),
  effort: z.string().min(1).max(32).optional(),
  personaPrompt: z.string().trim().min(1).max(500).optional()
});

const clientMessageSchema = z.discriminatedUnion("type", [
  z.object({
    version: z.literal(PROTOCOL_VERSION),
    type: z.literal("session.start"),
    payload: z.object({
      seed: z.number().int().optional(),
      model: z.string().min(1).max(120).optional(),
      effort: z.string().min(1).max(32).optional(),
      agents: z.array(sessionAgentSchema).min(1).max(4)
    })
  }),
  z.object({
    version: z.literal(PROTOCOL_VERSION),
    type: z.literal("god.send"),
    payload: z.object({ text: z.string().min(1), targetAgentId: z.string().min(1).optional() })
  }),
  z.object({
    version: z.literal(PROTOCOL_VERSION),
    type: z.literal("build.request"),
    payload: z.object({ goal: z.string().min(1) })
  }),
  z.object({
    version: z.literal(PROTOCOL_VERSION),
    type: z.literal("agent.pause"),
    payload: z.object({}).strict()
  }),
  z.object({
    version: z.literal(PROTOCOL_VERSION),
    type: z.literal("agent.resume"),
    payload: z.object({}).strict()
  }),
  z.object({
    version: z.literal(PROTOCOL_VERSION),
    type: z.literal("session.reset"),
    payload: z.object({
      seed: z.number().int().optional()
    })
  })
]);

export function parseClientMessage(raw: string): ClientMessage {
  const parsed = JSON.parse(raw) as unknown;
  return clientMessageSchema.parse(parsed);
}

export function encodeServerMessage(message: ServerMessage): string {
  return JSON.stringify(message);
}

