      version: PROTOCOL_VERSION,
      type: "session.state",
      payload: {
        phase: "running",
        paused: false,
        preparedSeed: null,
        threadIds: { gameplayByAgentId: { "agent-1": "thr-a" } },
        connected: true,
        runtime: {
